import os
import gen
from gen import page,home,palp,search
F2='<link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,600;9..144,800&family=Caveat:wght@700&family=Space+Grotesk:wght@500;700&display=swap" rel="stylesheet">'
def base(v):
  return f''':root{{{v['vars']}}}
*{{box-sizing:border-box}}body{{margin:0;font:15px/1.5 {v.get('body','Rubik')},sans-serif;color:var(--tx);background:var(--bgimg);background-attachment:fixed;min-height:100vh;padding:0 16px 96px}}
.top{{display:flex;gap:12px;align-items:center;padding:14px 0}}.logo{{font:800 21px {v.get('head','Rubik')};display:flex;align-items:center;gap:8px}}.logo:before{{content:"";width:22px;height:22px;border-radius:50%;background:linear-gradient(var(--sp) 0 46%,#222 46% 54%,#fff 54%)}}.logo span{{color:var(--ac)}}
.sbtn{{flex:1;max-width:520px;margin-left:auto;background:var(--pn);border:1px solid var(--ln);border-radius:var(--r);padding:12px 16px;text-align:left;color:var(--mu);font:inherit}}kbd{{float:right;font:12px 'JetBrains Mono';border:1px solid var(--ln);border-radius:6px;padding:0 6px}}
.hero,.ov,.pc,.tile,.bc,.facts>div,.pa,.st,.phead{{background:var(--pn);border:1px solid var(--ln);border-radius:var(--r);position:relative}}
.hero{{padding:22px;margin:8px 0}}.ask small,.ai small{{font:700 12px 'JetBrains Mono';color:var(--ac);letter-spacing:2px}}.ask small:before,.ai small:before{{content:"✦ "}}
h1{{font:800 clamp(26px,5vw,44px)/1.05 {v.get('head','Rubik')};margin:6px 0 14px}}.q{{color:var(--mu);margin-bottom:8px}}.ans{{font-size:16px}}
.fu{{display:inline-block;margin:10px 6px 0 0;padding:7px 13px;border-radius:99px;background:var(--fubg);border:1px solid var(--ac);color:var(--futx);font-size:13px}}
.sec{{font:700 18px {v.get('head','Rubik')};margin:26px 0 10px}}
.grid{{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px}}.pc{{display:block;padding:12px;overflow:hidden}}.pc img{{position:relative;width:100%;aspect-ratio:1;object-fit:contain;background:radial-gradient(circle,color-mix(in srgb,var(--e) 40%,transparent),transparent 65%)}}.pc em{{position:absolute;top:10px;right:12px;font:500 12px 'JetBrains Mono';color:var(--mu);font-style:normal;z-index:1}}.pc strong{{display:block;font-weight:700}}
.chip{{display:inline-flex;align-items:center;gap:5px;font-size:12px;padding:2px 9px;margin:2px 4px 0 0;border-radius:99px;background:color-mix(in srgb,var(--e) 22%,var(--chipbg));color:var(--tx)}}.chip:before{{content:"";width:7px;height:7px;border-radius:50%;background:var(--e)}}
.tiles{{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:10px}}.tile{{padding:16px;text-align:center;font-weight:600}}.tile i{{display:block;font-size:24px;font-style:normal;color:var(--ac)}}
.bl{{display:grid;gap:10px;grid-template-columns:repeat(auto-fill,minmax(260px,1fr))}}.bc{{padding:14px}}.bc b,.bc span{{display:block}}.bc span{{color:var(--mu);font-size:13px}}
.phead{{display:flex;gap:12px;align-items:center;padding:14px;background:linear-gradient(135deg,color-mix(in srgb,var(--e) 30%,var(--pn)),var(--pn))}}.phead img{{width:120px;height:120px;object-fit:contain}}.phead em{{font:500 13px 'JetBrains Mono';color:var(--mu);font-style:normal}}.phead h1{{margin:0 0 4px}}
.facts{{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}}.facts>div{{padding:10px 12px}}.facts small{{display:block;color:var(--mu);font-size:12px}}
.tabs{{display:flex;gap:4px;margin:16px 0 0;padding:4px;border-radius:var(--r);background:var(--pn);border:1px solid var(--ln);overflow:auto;position:sticky;top:8px;z-index:3}}.tabs a{{padding:8px 14px;border-radius:calc(var(--r) - 4px);color:var(--mu);white-space:nowrap}}.tabs a.on{{background:var(--ac);color:var(--ontx);font-weight:700}}
.stats{{display:grid;gap:8px}}.st{{display:grid;grid-template-columns:70px 1fr 40px;align-items:center;gap:8px;padding:10px 14px}}.st i{{height:8px;border-radius:9px;background:var(--chipbg)}}.st s{{display:block;height:100%;border-radius:9px;background:var(--bar)}}.st b{{font-family:'JetBrains Mono'}}
.wks{{display:flex;flex-wrap:wrap;gap:6px}}.wk{{padding:7px 12px;border-radius:12px;background:var(--pn);border:1px solid var(--ln)}}.wk b{{color:var(--ac)}}
.pas{{display:grid;gap:8px;grid-template-columns:repeat(auto-fill,minmax(220px,1fr))}}.pa{{padding:12px}}.pa b{{display:block}}.pa span{{color:var(--mu);font-size:13px}}
.bar{{position:fixed;left:16px;right:16px;bottom:14px;display:flex;justify-content:space-around;padding:12px;border-radius:var(--r);background:var(--pn);border:1px solid var(--ln);z-index:4}}
.ov{{max-width:720px;margin:16px auto;padding:16px}}.sbox{{display:flex;gap:10px;align-items:center;padding:6px 4px 12px;border-bottom:1px solid var(--ln)}}.sbox input{{flex:1;background:none;border:0;color:var(--tx);font:600 22px {v.get('head','Rubik')}}}
.ai{{margin:12px 0;padding:14px;border-radius:var(--r);background:var(--aibg);border:1px solid var(--ln)}}.grp{{font-size:12px;color:var(--mu);margin:14px 0 6px;letter-spacing:1px;text-transform:uppercase}}
.hit{{display:flex;gap:12px;align-items:center;padding:10px;border-radius:14px}}.hit:first-of-type{{background:var(--chipbg)}}.hit img,.ic{{width:44px;height:44px;border-radius:12px;background:var(--chipbg);display:grid;place-items:center}}.hit div{{flex:1}}.hit b,.hit span{{display:block}}.hit div span{{color:var(--mu);font-size:12px}}mark{{background:none;color:var(--ac);font-weight:800;text-decoration:underline}}
{v.get('extra','')}'''
GLASS='.hero,.ov,.pc,.tile,.bc,.facts>div,.pa,.st,.phead,.tabs,.bar,.sbtn{backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}'
V={}
V['d']=dict(name='Сфера + меню игры',askl='ПАЛ-ТЕРМИНАЛ · ИИ',h1='Спроси о мире палов',
 vars='--bg:#040b20;--pn:rgba(9,50,90,.55);--ln:rgba(86,150,199,.45);--tx:#f2f7ff;--mu:#b5cbe3;--ac:#fee707;--sp:#ff5a4e;--r:14px;--fubg:rgba(254,231,7,.08);--futx:#fee707;--chipbg:rgba(255,255,255,.08);--ontx:#040b20;--bar:linear-gradient(90deg,#5696c7,#fee707);--aibg:linear-gradient(135deg,rgba(255,90,78,.16),rgba(86,150,199,.18));--bgimg:radial-gradient(900px 500px at 10% -10%,rgba(255,90,78,.28),transparent 60%),radial-gradient(900px 600px at 100% 0,rgba(17,97,147,.6),transparent 60%),#040b20',
 extra=GLASS+'''.hero:before,.phead:before,.ov:before{content:"";position:absolute;inset:6px;pointer-events:none;background:linear-gradient(var(--ac),var(--ac)) 0 0/14px 2px,linear-gradient(var(--ac),var(--ac)) 0 0/2px 14px,linear-gradient(var(--ac),var(--ac)) 100% 100%/14px 2px,linear-gradient(var(--ac),var(--ac)) 100% 100%/2px 14px;background-repeat:no-repeat}
.sec{font:700 12px 'JetBrains Mono';letter-spacing:3px;text-transform:uppercase;color:var(--mu)}.sec:before{content:"◆ ";color:var(--sp)}.tabs a{transform:skewX(-10deg)}.pc em{color:var(--ac)}h1{font-style:italic}''')
V['e']=dict(name='Сфера днём (светлая)',askl='ИИ-ПОМОЩНИК',h1='Солнечный Палпагос. Спрашивай.',
 vars='--pn:rgba(255,255,255,.62);--ln:rgba(40,70,110,.18);--tx:#152238;--mu:#3d4d63;--ac:#c2362b;--sp:#e5483d;--r:22px;--fubg:rgba(255,255,255,.7);--futx:#a42a20;--chipbg:rgba(21,34,56,.07);--ontx:#fff;--bar:linear-gradient(90deg,#e5483d,#2f9e8a);--aibg:linear-gradient(135deg,rgba(244,160,129,.35),rgba(161,237,184,.4));--bgimg:radial-gradient(900px 500px at 0 -10%,#f4a08188,transparent 60%),radial-gradient(800px 500px at 100% 10%,#a1edb899,transparent 60%),linear-gradient(#d6eff9,#f6fbff 500px)',
 extra=GLASS+'.pc,.hero{box-shadow:0 12px 30px -12px rgba(21,34,56,.25)}.chip{color:#152238}')
V['f']=dict(name='Сканер Палдека',askl='SCAN://PALDECK',h1='Наведи сканер на пала',head='Space Grotesk',body='Space Grotesk',
 vars='--pn:#07161a;--ln:#1f5f5a;--tx:#dcfff4;--mu:#8fc9b8;--ac:#4dffc3;--sp:#ff5a4e;--r:2px;--fubg:transparent;--futx:#4dffc3;--chipbg:#0d2a2c;--ontx:#021012;--bar:repeating-linear-gradient(90deg,#4dffc3 0 6px,transparent 6px 8px);--aibg:#04211f;--bgimg:linear-gradient(rgba(77,255,195,.05) 1px,transparent 1px) 0 0/100% 24px,linear-gradient(90deg,rgba(77,255,195,.05) 1px,transparent 1px) 0 0/24px 100%,#020a0c',
 extra='.pc img{background:none;filter:drop-shadow(0 0 10px color-mix(in srgb,var(--e) 70%,transparent))}.pc:after{content:"";position:absolute;inset:8px;border:1px dashed var(--ln);pointer-events:none}.phead img{border:1px solid var(--ac);outline:6px solid rgba(77,255,195,.08)}.sec{font:700 13px "JetBrains Mono";color:var(--ac);text-transform:uppercase}.sec:before{content:"> "}.sec:after{content:"_";animation:b 1s steps(1) infinite}@keyframes b{50%{opacity:0}}h1{text-transform:uppercase;letter-spacing:1px}.chip{border-radius:2px;border:1px solid var(--e)}.fu{border-radius:2px}.logo:before{border-radius:2px}')
V['g']=dict(name='Закат над островами',askl='ВЕЧЕРНИЙ СОВЕТ',h1='Пока солнце садится — спроси',head='Fraunces',
 vars='--pn:rgba(47,36,30,.62);--ln:rgba(240,216,136,.28);--tx:#fff6e6;--mu:#f0d8b8;--ac:#ffd27a;--sp:#ff6a4a;--r:26px;--fubg:rgba(255,210,122,.1);--futx:#ffd27a;--chipbg:rgba(255,246,230,.1);--ontx:#2f241e;--bar:linear-gradient(90deg,#ff6a4a,#ffd27a);--aibg:linear-gradient(135deg,rgba(255,106,74,.25),rgba(240,216,136,.15));--bgimg:linear-gradient(180deg,#f0a35e 0,#c2614a 180px,#5a2f3a 420px,#2a1a22 700px)',
 extra=GLASS+'.hero{border-radius:40px 40px 40px 8px}.pc{border-radius:999px 999px 26px 26px;padding-top:18px}.pc img{background:radial-gradient(circle at 50% 70%,#ffd27a55,transparent 60%)}.sec{font-style:italic}')
V['h']=dict(name='Верстак: дерево и бумага',askl='ЗАПИСКИ ТРЕНЕРА',h1='Журнал тренера палов',head='Caveat',body='Nunito',
 vars='--pn:#f6ecd9;--ln:#8f5334;--tx:#2b1a10;--mu:#5c3d2a;--ac:#8a2f17;--sp:#c9412f;--r:10px;--fubg:#fff8ea;--futx:#7a2914;--chipbg:#eadbc0;--ontx:#fff6e6;--bar:#6d8d5b;--aibg:#fff4c9;--bgimg:url(../ref/pp_bg-features.jpg) center/cover,#5c3625',
 extra='.hero,.ov,.pc,.tile,.bc,.facts>div,.pa,.st,.phead{border:2px dashed #8f533499;box-shadow:0 0 0 4px #f6ecd9,0 10px 18px rgba(0,0,0,.45)}.pc:nth-child(odd){transform:rotate(-1.2deg)}.pc:nth-child(even){transform:rotate(1deg)}.pc:before{content:"";position:absolute;top:-6px;left:40%;width:40px;height:14px;background:#e8d27ccc;transform:rotate(-4deg);z-index:2}h1,.sec,.logo{font-family:Caveat}h1{font-size:clamp(34px,7vw,56px)}.sec{font-size:30px;color:#fff3dc;text-shadow:0 2px 4px #000}.top .logo{color:#fff3dc}.top .logo span{color:#ffd27a}.ask small,.ai small{font-family:Nunito}.bar{background:#3a2216;color:#fff3dc}')
for k,v in V.items():
  css=base(v);c=dict(askl=v['askl'],h1=v['h1'])
  os.makedirs(f'concept_{k}',exist_ok=True)
  for n,f in [('home',home),('pal',palp),('search',search)]:
    open(f'concept_{k}/{n}.html','w').write(page(css,f(c),n).replace('</head>',F2+'</head>'))
